42	  const int64_t corner_sq = cx * cx + cy * cy;
43	  int64_t full = 0;
44	  while (full * full < corner_sq) full++;
45	  const int64_t r = (int64_t)(ratio * (double)full);
46	  const int64_t reach = cy > c->h - 1 - cy ? cy : c->h - 1 - cy;
47	  int64_t dx = r;
