1	#include <sanitizer/allocator_interface.h>
2	#include <stdint.h>
3	#include <stdlib.h>
4	#include <time.h>
5	#include <unity.h>
6	
7	#include "core/canvas.h"
8	#include "doubletime.h"
9	#include "erase.h"
10	#include "runner/hack_runner.h"
11	#include "x11shim/xshim.h"
12	
13	enum { kSize = 466 };
14	static const uint16_t kPicture = 0x1234;
15	
16	static Canvas cv;
17	static Display *dpy;
18	static double now;
19	static size_t live_before;
20	
21	static double test_clock(void) { return now; }
22	
23	void setUp(void) {
24	  live_before = __sanitizer_get_current_allocated_bytes();
25	  TEST_ASSERT_EQUAL_INT(0, canvas_init(&cv, kSize, kSize, malloc));
26	  dpy = xshim_open_display(&cv);
27	  now = 1000.0;
28	  xshim_set_clock(test_clock);
29	  xshim_erase_force_effect(0);
30	  canvas_clear(&cv, kPicture);
31	}
32	
33	void tearDown(void) {
34	  xshim_erase_force_effect(-1);
35	  xshim_set_clock(NULL);
36	  xshim_close_display(dpy);
37	  canvas_free(&cv);
38	  TEST_ASSERT_EQUAL_UINT64_MESSAGE(live_before,
39	                                   __sanitizer_get_current_allocated_bytes(),
40	                                   "test leaked memory");
41	}
42	
43	static int count_pixels(uint16_t color) {
44	  int n = 0;
45	  for (int i = 0; i < kSize * kSize; i++) n += cv.px[i] == color;
46	  return n;
47	}
48	
49	/* Runs a wipe the way a hack drives it: a first call, a dwell, then steps
50	 * every `interval` seconds. Returns the seconds from the first step to the
51	 * call that returned NULL. */
52	static double run_wipe(double interval) {
53	  eraser_state *st = erase_window(dpy, XSHIM_WINDOW, NULL);
54	  TEST_ASSERT_NOT_NULL(st);
55	  now += 5.0;
56	  st = erase_window(dpy, XSHIM_WINDOW, st);
57	  const double first_step = now;
58	  int guard = 0;
59	  while (st) {
60	    now += interval;
61	    st = erase_window(dpy, XSHIM_WINDOW, st);
62	    TEST_ASSERT_TRUE_MESSAGE(++guard < 10000, "wipe never ended");
63	  }
64	  return now - first_step;
65	}
66	
67	void test_first_call_draws_nothing_and_returns_a_state(void) {
68	  eraser_state *st = erase_window(dpy, XSHIM_WINDOW, NULL);
69	  TEST_ASSERT_NOT_NULL(st);
70	  TEST_ASSERT_EQUAL_INT(kSize * kSize, count_pixels(kPicture));
71	  eraser_free(st);
72	}
73	
74	void test_dwell_is_not_counted(void) {
75	  eraser_state *st = erase_window(dpy, XSHIM_WINDOW, NULL);
76	  now += 5.0;
77	  eraser_state *again = erase_window(dpy, XSHIM_WINDOW, st);
78	  TEST_ASSERT_NOT_NULL(again);
79	  TEST_ASSERT_EQUAL_INT(kSize * kSize, count_pixels(kPicture));
80	  eraser_free(again);
81	}
82	
83	void test_wipe_ends_one_second_after_its_first_step(void) {
84	  const double intervals[] = {0.010, 0.033};
85	  for (int i = 0; i < 2; i++) {
86	    canvas_clear(&cv, kPicture);
87	    const double took = run_wipe(intervals[i]);
88	    TEST_ASSERT_TRUE_MESSAGE(took >= 1.0 - 1e-6, "ended early");
89	    TEST_ASSERT_TRUE_MESSAGE(took <= 1.0 + intervals[i] + 1e-6, "ended late");
90	    TEST_ASSERT_EQUAL_INT(kSize * kSize, count_pixels(0));
91	  }
92	}
93	
94	void test_a_late_step_finishes_cleanly(void) {
95	  eraser_state *st = erase_window(dpy, XSHIM_WINDOW, NULL);
96	  st = erase_window(dpy, XSHIM_WINDOW, st);
97	  now += 10.0;
98	  st = erase_window(dpy, XSHIM_WINDOW, st);
99	  TEST_ASSERT_NULL(st);
100	  TEST_ASSERT_EQUAL_INT(kSize * kSize, count_pixels(0));
101	}
102	
103	void test_uses_the_window_background(void) {
104	  XSetWindowBackground(dpy, XSHIM_WINDOW, 0x00F8);
105	  eraser_state *st = erase_window(dpy, XSHIM_WINDOW, NULL);
106	  st = erase_window(dpy, XSHIM_WINDOW, st);
107	  now += 0.5;
108	  st = erase_window(dpy, XSHIM_WINDOW, st);
109	  TEST_ASSERT_NOT_NULL(st);
110	  TEST_ASSERT_GREATER_THAN_INT(0, count_pixels(0x00F8));
111	  TEST_ASSERT_EQUAL_INT(0, count_pixels(0));
112	  eraser_free(st);
113	
114	  canvas_clear(&cv, kPicture);
115	  run_wipe(0.033);
116	  TEST_ASSERT_EQUAL_INT(kSize * kSize, count_pixels(0x00F8));
117	}
118	
119	void test_a_second_wipe_starts_fresh(void) {
120	  run_wipe(0.033);
121	  canvas_clear(&cv, kPicture);
122	  eraser_state *st = erase_window(dpy, XSHIM_WINDOW, NULL);
123	  TEST_ASSERT_NOT_NULL(st);
124	  TEST_ASSERT_EQUAL_INT(kSize * kSize, count_pixels(kPicture));
125	  eraser_free(st);
126	}
127	
128	void test_a_step_marks_rows_dirty(void) {
129	  eraser_state *st = erase_window(dpy, XSHIM_WINDOW, NULL);
130	  st = erase_window(dpy, XSHIM_WINDOW, st);
131	  canvas_clear_dirty(&cv);
132	  now += 0.5;
133	  st = erase_window(dpy, XSHIM_WINDOW, st);
134	  TEST_ASSERT_NOT_NULL(st);
135	  int dirty_rows = 0, x0, x1;
136	  for (int y = 0; y < kSize; y++) dirty_rows += canvas_dirty_row(&cv, y, &x0, &x1);
137	  TEST_ASSERT_GREATER_THAN_INT(0, dirty_rows);
138	  TEST_ASSERT_LESS_THAN_INT(kSize * kSize, count_pixels(kPicture) + 1);
139	  eraser_free(st);
140	}
141	
142	enum { kEffects = 4 };
143	
144	/* Starts a wipe and takes its first step, so the clock starts at *start. */
145	static eraser_state *begin_wipe(int effect, double *start) {
146	  srandom(1);
147	  xshim_erase_force_effect(effect);
148	  eraser_state *st = erase_window(dpy, XSHIM_WINDOW, NULL);
149	  st = erase_window(dpy, XSHIM_WINDOW, st);
150	  *start = now;
151	  return st;
152	}
153	
154	static eraser_state *step_to(eraser_state *st, double start, double ratio) {
155	  now = start + ratio;
156	  return erase_window(dpy, XSHIM_WINDOW, st);
157	}
158	
159	static double cleared_fraction(uint16_t background) {
160	  return (double)count_pixels(background) / (kSize * kSize);
161	}
162	
163	void test_effect_count_is_four(void) {
164	  TEST_ASSERT_EQUAL_INT(kEffects, xshim_erase_effect_count());
165	}
166	
167	void test_cleared_area_grows_and_ends_complete(void) {
168	  for (int e = 0; e < kEffects; e++) {
